const input = $input.first().json;

const content = JSON.parse(input["Content JSON"]);

return [
  {
    json: content
  }
];

const nextNumber = Number($json.Value);

const contentId = `PIV-${String(nextNumber).padStart(3, '0')}`;

return [
  {
    json: {
      "Content ID": contentId
    }
  }
];

const geminiText = $json.content.parts[0].text;

const aiOutput = JSON.parse(geminiText);

const planning = $("Restore content context").first().json;

const video = aiOutput.OUTPUT_2;
const image = aiOutput.OUTPUT_3;

// Format the video direction into one readable field
const videoDirection = `
FORMAT: ${video.format}
DURATION: ${video.duration}
MOOD: ${video.mood}

VISUAL CONCEPT:
${video.visual_concept}

SHOTS:
${video.shots.map((shot, index) => {
  const description = typeof shot === "string"
    ? shot
    : Object.values(shot)[0];

  return `${index + 1}. ${description}`;
}).join("\n")}

VISUAL ELEMENTS:
${video.visual_elements.map(item => `â€¢ ${item}`).join("\n")}

AVOID:
${video.avoid.map(item => `â€¢ ${item}`).join("\n")}
`.trim();

// Format the image direction into one readable field
const imageDirection = `
FORMAT: ${image.format}

VISUAL CONCEPT:
${image.visual_concept}

SUBJECT:
${image.subject}

COMPOSITION:
${image.composition}

ENVIRONMENT:
${image.environment}

LIGHTING:
${image.lighting}

MOOD:
${image.mood}

TEXT OVERLAY:
${image.text_overlay || "None"}

VISUAL ELEMENTS:
${image.visual_elements.map(item => `â€¢ ${item}`).join("\n")}

AVOID:
${image.avoid.map(item => `â€¢ ${item}`).join("\n")}
`.trim();

return [
  {
    json: {
      "Content ID": planning["Content ID"],
      "Topic": planning["Topic"],
      "Platform": aiOutput.OUTPUT_1.platform,
      "AI Social Post": aiOutput.OUTPUT_1.post_content,
      "AI Video Direction": videoDirection,
      "AI Image Direction": imageDirection,
      "Review Status": "Pending"
    }
  }
];
